// === Tab: main ===
// Rainbow Metaballs Shader（動きを遅くしたバージョン）

let metaballShader; // シェーダー変数
const NUM_BALLS = 13; // メタボールの数
const metaballs = []; // メタボールの配列

function getShader(_renderer) {
  const vert = `
    attribute vec3 aPosition;
    attribute vec2 aTexCoord;
    varying vec2 vTexCoord;

    void main() {
      vTexCoord = aTexCoord;
      vec4 pos = vec4(aPosition, 1.0);
      pos.xy = pos.xy * 2.0 - 1.0;
      gl_Position = pos;
    }
  `;

  const frag = `
    precision highp float;
    varying vec2 vTexCoord;
    uniform vec3 metaballs[${NUM_BALLS}];

    const float WIDTH = ${window.innerWidth}.0;
    const float HEIGHT = ${window.innerHeight}.0;

    vec3 hsv2rgb(vec3 c) {
      vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
      vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
      return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
    }

    void main() {
      float x = vTexCoord.x * WIDTH;
      float y = vTexCoord.y * HEIGHT;
      float v = 0.0;

      for (int i = 0; i < ${NUM_BALLS}; i++) {
        vec3 ball = metaballs[i];
        float dx = ball.x - x;
        float dy = ball.y - y;
        float r = ball.z;
        v += r * r / (dx * dx + dy * dy);
      }

      if (0.9 < v && v < 1.1) {
        float a = (v - 0.9) * 4.0;
        gl_FragColor = vec4(hsv2rgb(vec3(a, 1.0, 1.0)), 1.0);
      } else {
        gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
      }
    }
  `;

  return createShader(vert, frag);
}

function preload() {
  metaballShader = getShader(this._renderer); // シェーダー取得
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL); // キャンバス作成
  noStroke(); // 枠線なし
  shader(metaballShader); // シェーダー適用

  for (let i = 0; i < NUM_BALLS; i++) {
    metaballs.push(new Metaball()); // メタボール作成
  }
}

function draw() {
  let data = [];
  for (let ball of metaballs) {
    ball.update(); // メタボールの位置更新
    data.push(ball.pos.x, ball.pos.y, ball.radius); // データ追加
  }

  metaballShader.setUniform("metaballs", data); // uniform送信
  rect(-width / 2, -height / 2, width, height); // 全画面にシェーダー適用
}

class Metaball {
  constructor() {
    const size = pow(random(), 2); // サイズをランダムに
    this.radius = 100 * size + 20; // 半径計算
    this.vel = p5.Vector.random2D().mult(2 * (1 - size) + 0.5); // 🌟 速度をかなり遅く設定
    this.pos = createVector(width / 2, height / 2); // 初期位置
  }

  update() {
    this.pos.add(this.vel); // 位置更新
    if (this.pos.x < this.radius || this.pos.x > width - this.radius) {
      this.vel.x *= -1; // 壁で反射（横）
    }
    if (this.pos.y < this.radius || this.pos.y > height - this.radius) {
      this.vel.y *= -1; // 壁で反射（縦）
    }
  }
}

